    d = 2
    while d * d <= n:
        if n % (d * d) == 0:
            return False
        d += 1
    return True

def check_p(p):
    # primes less than p
    primes = []
    for i in range(2, p):
        is_prime = True
        for j in range(2, int(i**0.5)+1):
            if i % j == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(i)
    for q in primes:
        r = p % q
        if not is_square_free(r):
            return False, q, r
    return True, None, None

