{"operation":"run_python","code":"def max_sum(n):
    best = 0
    for mask in range(1 << n):
        a = [(mask >> i) & 1 for i in range(n)]
        s = 0
        for i in range(n):
            for j in range(i+1, n):
                s += (j - i) * abs(a[j] - a[i])
        if s > best:
            best = s
    return best

for n in range(1, 8):
    print(f"n={n}, max={max_sum(n)}")
"}

