{"operation":"run_python","code":"import math

def prob_not_upset(n):
    # n is number of pairs (so n left, n right)
    # 7 days
    # He gets upset if at any point he wants a slipper type and count == 0
    # This is equivalent to: total Left choices <= n AND total Right choices <= n
    p = 0
    for k in range(8): # number of Left choices
        if k <= n and (7 - k) <= n:
            p += math.comb(7, k) * (0.5 ** 7)
    return p

for n in range(1, 8):
    print(f"n={n}, prob={prob_not_upset(n)}")"}

